-- 000004_update_lesson_content.down.sql
UPDATE lessons SET content = E'税金は、教育・医療・インフラなど社会を支えるための資金です。' WHERE id = 1;
UPDATE lessons SET content = E'支給・控除・差引支給額の見方を理解します。' WHERE id = 2;
UPDATE lessons SET content = E'必要書類を早めに準備することが重要です。' WHERE id = 3;
UPDATE lessons SET content = E'税金には国に納める「国税」と地方自治体に納める「地方税」があります。代表的な国税は所得税・法人税・消費税などで、地方税には住民税・固定資産税などがあります。' WHERE id = 4;
UPDATE lessons SET content = E'直接税は税を負担する人が直接国・自治体に納める税（所得税・住民税など）です。間接税は消費税のように、税を負担する消費者とは別の事業者が代わりに納める税です。' WHERE id = 5;
UPDATE lessons SET content = E'給与から引かれる社会保険料は「健康保険」「介護保険（40歳以上）」「厚生年金保険」「雇用保険」の4種類です。それぞれ労使折半で負担しますが、雇用保険のみ会社の負担率が高めに設定されています。' WHERE id = 6;
UPDATE lessons SET content = E'源泉徴収とは、会社が従業員の代わりに所得税を計算・納付する仕組みです。年末調整で過不足を精算し、納めすぎた税金は還付されます。' WHERE id = 7;
UPDATE lessons SET content = E'ふるさと納税は、応援したい自治体に寄付することで税金控除が受けられる制度です。寄付金額から自己負担2,000円を引いた全額が所得税・住民税から控除されます。さらに返礼品（特産品など）がもらえるのが魅力です。' WHERE id = 8;
UPDATE lessons SET content = E'ワンストップ特例制度を使うと、確定申告不要でふるさと納税の控除が受けられます。ただし寄付先が5自治体以内・給与所得者であることが条件です。申請書を各自治体に翌年1月10日までに送付する必要があります。' WHERE id = 9;
UPDATE lessons SET content = E'確定申告書はe-Tax（オンライン）、税務署への郵送、窓口持参のいずれかで提出できます。e-Taxはマイナンバーカードとスマートフォンがあれば自宅から24時間手続き可能です。' WHERE id = 10;
UPDATE lessons SET content = E'年間の医療費が10万円（所得200万円以下の場合は所得の5%）を超えた場合は医療費控除が受けられます。住宅ローン控除は、ローン残高の0.7%が最長13年間税額から直接控除されます。' WHERE id = 11;
UPDATE lessons SET content = E'給与以外の所得（副業収入）が年間20万円を超える場合は確定申告が必要です。フリマアプリの売上・YouTube収益・クラウドソーシングなど幅広い収入が対象となります。' WHERE id = 12;
UPDATE lessons SET content = E'副業に直接関連する費用は経費として認められます。具体例として、パソコン・カメラなどの機材費、通信費、仕事用の書籍代、交通費などが挙げられます。プライベートと按分が必要なものは合理的な割合で計上します。' WHERE id = 13;
UPDATE lessons SET content = E'iDeCo（個人型確定拠出年金）は、掛金が全額所得控除・運用益が非課税・受取時も控除対象という三重の節税メリットがあります。ただし60歳まで原則引き出しできない点に注意が必要です。' WHERE id = 14;
UPDATE lessons SET content = E'新NISAは「つみたて投資枠（年120万円）」と「成長投資枠（年240万円）」の2つから構成されます。どちらの枠も運用益・配当が非課税です。長期・積立・分散投資を基本に、ライフプランに合わせて活用しましょう。' WHERE id = 15;
